// LaunchBuilder v62 — robotArt.js
// The AI Consultant robot pictures. Loaded only after the dashboard is on screen, so the first load stays light.
const css = `.rb4-bubble{background-image:url(data:image/webp;base64,)}\n.rb4-spark{background-image:url(data:image/webp;base64,)}\n.rb4-badge1{background-image:url(data:image/webp;base64,)}\n.rb4-badge2{background-image:url(data:image/webp;base64,)}\n.rb4-arm{background-image:url(data:image/webp;base64,)}\n.rb4-body{background-image:url(data:image/webp;base64,)}\n`;
export default function injectRobotArt() {
  if (typeof document === "undefined" || document.getElementById("lb-robot-art")) return;
  const s = document.createElement("style"); s.id = "lb-robot-art"; s.textContent = css; document.head.appendChild(s);
}
